def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 70
    WATER_REQ = 13

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    aggressive_bids = []
    desperate_count = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev:
                bid = prev.get('bid')
                if bid is not None:
                    prev_bids.append(bid)
                    if bid >= DAILY_SALARY * 0.85:
                        aggressive_bids.append(bid)

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.25))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    tight_supply = supply <= 17
    medium_supply = supply <= 20

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water_days >= 2:
        urgency += 4
    elif no_water_days >= 1:
        urgency += 2
    if tight_supply:
        urgency += 2
    elif medium_supply:
        urgency += 1
    if desperate_count >= 2:
        urgency += 1

    if urgency >= 7:
        bid = max(DAILY_SALARY * 1.15, highest_prev + 3.0)
    elif urgency >= 5:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 2.0 if highest_prev > 0 else DAILY_SALARY * 0.95)
    elif urgency >= 3:
        if highest_prev >= 140:
            bid = DAILY_SALARY * 0.58
        else:
            bid = max(DAILY_SALARY * 0.68, min(highest_prev + 1.5, DAILY_SALARY * 0.9))
    else:
        if highest_prev >= 140 or avg_prev >= 120:
            bid = DAILY_SALARY * 0.32
        elif highest_prev >= DAILY_SALARY * 0.9:
            bid = DAILY_SALARY * 0.42
        else:
            bid = max(DAILY_SALARY * 0.38, min(highest_prev + 1.0, DAILY_SALARY * 0.62)) if highest_prev > 0 else DAILY_SALARY * 0.4

    if day >= 8 and hp > 4 and no_water_days == 0:
        bid = min(bid, DAILY_SALARY * 0.5)

    if budget < DAILY_SALARY * 0.8:
        bid = min(bid, budget)
    else:
        reserve_floor = 0.0
        if day <= 7:
            reserve_floor = DAILY_SALARY * 0.35
        bid = min(bid, max(0.0, budget - reserve_floor))

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, DAILY_SALARY * 0.9))

    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    bid_value = DAILY_SALARY * 0.7

    if my_hp <= 2:
        bid_value = DAILY_SALARY * 1.05
    elif my_hp <= 4:
        bid_value = DAILY_SALARY * 0.9
    elif my_hp >= 8:
        bid_value = DAILY_SALARY * 0.65

    highest_prev_bid = 0
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            highest_prev_bid = max(highest_prev_bid, prev_trace['bid'])

    if highest_prev_bid > 0:
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            bid_value = max(bid_value, highest_prev_bid + (DAILY_SALARY * 0.05))
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            bid_value = max(bid_value, highest_prev_bid + (DAILY_SALARY * 0.02))
        else:
            if my_hp >= 8:
                bid_value = min(bid_value, highest_prev_bid + (DAILY_SALARY * 0.1))
            else:
                bid_value = max(bid_value, DAILY_SALARY * 0.6)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2:
        bid_value = max(bid_value, DAILY_SALARY * 0.95)
        if my_hp <= 4:
            bid_value = max(bid_value, DAILY_SALARY * 1.1)

    final_bid = min(my_budget, bid_value)
    final_bid = max(0.01, final_bid)

    return final_bid
